                <?php foreach ($transactions as $transaction): ?>
                    <?php $isRefund = $transaction['transaction_type'] === 'refund'; $isPending = $transaction['transaction_type'] === 'pending'; $statusLabel = ucfirst((string) $transaction['transaction_status']); $statusClass = match ($transaction['transaction_status']) { 'pending' => 'bg-yellow-500 text-black', 'recorded' => 'bg-green-500 text-white', default => 'bg-red-500 text-white' }; ?>
                    <tr>
                        <td class="whitespace-nowrap px-5 py-4 text-zinc-600 dark:text-zinc-300"><?= e(date('d M Y, H:i', strtotime((string) $transaction['occurred_at']))) ?></td>
