                        <td class="px-5 py-4"><?= $isPending ? '—' : e(strtoupper((string) $transaction['method']) === 'KHQR' ? 'KHQR' : 'Cash') ?></td>
                        <td class="whitespace-nowrap px-5 py-4 text-right font-semibold <?= $isRefund ? 'text-red-700 dark:text-red-300' : '' ?>"><?= $isRefund ? '−' : '' ?><?= e(format_khr($transaction['amount'])) ?> KHR</td>
                        <td class="max-w-xs px-5 py-4"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= e($statusClass) ?>"><?= e(t($statusLabel)) ?></span><?php if (!empty($transaction['reason']) || !empty($transaction['void_reason'])): ?><p class="mt-1 break-words text-xs text-zinc-500 dark:text-zinc-400"><?= e($transaction['reason'] ?? $transaction['void_reason']) ?></p><?php endif; ?></td>
                        <td class="px-5 py-4"><?= e($transaction['username']) ?></td>
                        <td class="px-5 py-4"><div class="flex justify-end gap-2"><a href="/orders/<?= (int) $transaction['order_id'] ?><?= $transaction['transaction_type'] === 'payment' ? '?payment_id=' . (int) $transaction['payment_id'] . '&amp;return=' . rawurlencode('/payments' . (!empty($_SERVER['QUERY_STRING']) ? '?' . $_SERVER['QUERY_STRING'] : '')) : '' ?>" <?php if ($transaction['transaction_type'] === 'payment'): ?>data-payment-view data-payment-details-url="/orders/<?= (int) $transaction['order_id'] ?>/payment-details?payment_id=<?= (int) $transaction['payment_id'] ?>"<?php endif; ?> title="<?= e(t($transaction['transaction_type'] === 'payment' ? 'View payment details' : 'View order')) ?>" class="rounded-md border border-zinc-200 px-3 py-1.5 text-xs font-semibold text-zinc-700 hover:border-primary hover:text-primary dark:border-zinc-700 dark:text-zinc-200"><?= e(t('View')) ?></a><?php if ($transaction['transaction_type'] === 'payment' && $transaction['transaction_status'] === 'recorded'): ?><a href="/orders/<?= (int) $transaction['order_id'] ?>?print=payment&amp;payment_id=<?= (int) $transaction['payment_id'] ?>&amp;size=80" title="<?= e(t('Print receipt for payment #{payment}', ['payment' => (int) $transaction['payment_id']])) ?>" class="whitespace-nowrap rounded-md bg-primary px-3 py-1.5 text-xs font-semibold text-white hover:bg-primary-hover"><?= e(t('Print Receipt')) ?></a><?php elseif ($transaction['transaction_type'] === 'payment'): ?><span class="px-2 py-1.5 text-xs text-zinc-400" title="<?= e(t('Corrected payments cannot be printed')) ?>">—</span><?php endif; ?></div></td>
                    </tr>
                <?php endforeach; ?>
                <?php if ($transactions === []): ?><tr><td colspan="8" class="px-5 py-12 text-center text-zinc-500 dark:text-zinc-400"><?= e(t('No payment transactions found.')) ?></td></tr><?php endif; ?>
            </tbody>
        </table></div>
        <?php $first = $total === 0 ? 0 : (($page - 1) * $perPage + 1); $last = min($page * $perPage, $total); ?>
        <div class="flex flex-wrap items-center justify-between gap-3 border-t border-zinc-100 px-5 py-3 dark:border-zinc-800"><p id="payments-result-count" class="text-xs text-zinc-500 dark:text-zinc-400"><?= e(t('Showing {first}–{last} of {total} transactions.', ['first' => $first, 'last' => $last, 'total' => $total])) ?></p><nav id="payments-pagination" aria-label="Payment pages" class="flex items-center gap-2"><?php if ($page > 1): $previousParams = $_GET; $previousParams['page'] = $page - 1; ?><a href="/payments?<?= e(http_build_query($previousParams)) ?>" data-payment-page="<?= $page - 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800"><?= e(t('Previous')) ?></a><?php endif; ?><span class="px-2 text-xs text-zinc-500 dark:text-zinc-400"><?= e(t('Page {page} of {pages}', ['page' => $page, 'pages' => $totalPages])) ?></span><?php if ($page < $totalPages): $nextParams = $_GET; $nextParams['page'] = $page + 1; ?><a href="/payments?<?= e(http_build_query($nextParams)) ?>" data-payment-page="<?= $page + 1 ?>" class="rounded-md px-3 py-1.5 text-sm text-zinc-600 hover:bg-zinc-100 dark:text-zinc-300 dark:hover:bg-zinc-800"><?= e(t('Next')) ?></a><?php endif; ?></nav></div>
